; ============================================================
; function spawn (turbo mode)
; ============================================================

p_spawn:

			; Main.bas 664: Dim m As Integer

			; Main.bas 665: For m = 0 To NE - 1
			dw kw_ztov, var_spawn_m
for134_t:

			; Main.bas 666: If ek(m) = 0 Then
			dw kw_aget, arr_ek, var_spawn_m, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse, if135_1

			; Main.bas 667: ek(m) = kd : ex(m) = x * 16 + 8 : ey(m) = y * 16 + 8 : evx(m) = 0 : evy(m) = 0
			dw kw_aset, arr_ek, var_spawn_m, var_spawn_kd
			dw kw_mulvl, var_spawn_x, 16, tmp1
			dw kw_addl, tmp1, 8, tmp1
			dw kw_aset, arr_ex, var_spawn_m, tmp1
			dw kw_mulvl, var_spawn_y, 16, tmp1
			dw kw_addl, tmp1, 8, tmp1
			dw kw_aset, arr_ey, var_spawn_m, tmp1
			dw kw_asetl, arr_evx, var_spawn_m, 0
			dw kw_asetl, arr_evy, var_spawn_m, 0

			; Main.bas 668: ehp(m) = khp(kd) : et(m) = 0 : ea(m) = 0 : ef(m) = 0
			dw kw_aget, arr_khp, var_spawn_kd, tmp1
			dw kw_aset, arr_ehp, var_spawn_m, tmp1
			dw kw_asetl, arr_et, var_spawn_m, 0
			dw kw_asetl, arr_ea, var_spawn_m, 0
			dw kw_asetl, arr_ef, var_spawn_m, 0

			; Main.bas 669: If loopN = 2 Then ehp(m) = ehp(m) + ehp(m) \ 4
			dw kw_cpeqvl, var_loopn, 2
			dw kw_goto_iffalse, if136_1
			dw kw_aget, arr_ehp, var_spawn_m, tmp1
			dw kw_aget, arr_ehp, var_spawn_m, tmp2
			dw kw_divvl, tmp2, 4, tmp2
			dw kw_add, tmp1, tmp2, tmp1
			dw kw_aset, arr_ehp, var_spawn_m, tmp1
if136_1:

			; Main.bas 670: efire(m) = -1
			dw kw_asetl, arr_efire, var_spawn_m, -1

			; Main.bas 671: If kd = K_POP Then
			dw kw_cpeqvl, var_spawn_kd, 1
			dw kw_goto_iffalse, if137_1

			; Main.bas 672: evy(m) = 20
			dw kw_asetl, arr_evy, var_spawn_m, 20

			; Main.bas 673: If Rnd(5) < stage + loopN Then efire(m) = 30 + Rnd(50)
			dw kw_rndl, 5, tmp0
